                c1 = line1.find(ln)
                c2 = line2.find(fn)
                if abs(c1 - c2) < 30:
                    found_people.append({
                        'name': full_name,
                        'first_name': fn,
                        'last_name': ln,
                        'balance': bal,
                        'rows': [r, r+1],
                        'cols': list(range(min(c1, c2), max(c1+len(ln), c2+len(fn))))
                    })
                    for c in range(c1, c1+len(ln)):
                        name_pixels.add((r, c))
