    # Top zone: 1-3 rows above
    p['top_zone'] = []
    for r in range(max(0, r_min - 3), r_min):
        for c in range(max(0, c_min - 5), min(W, c_max + 6)):
            p['top_zone'].append((r, c))

    # Bottom zone: 1-3 rows below
    p['bottom_zone'] = []
    for r in range(r_max + 1, min(H, r_max + 4)):
        for c in range(max(0, c_min - 5), min(W, c_max + 6)):
            p['bottom_zone'].append((r, c))

# Map each top zone pixel to the person's index
